#include <alloc.h>
#include <algobase.h>
#include <uninitialized.h>
#include <construct.h>

struct light_source;

template<class T>
struct my_allocator : public alloc {
};

template<class T, class Alloc>
class vector {
    T *_M_start;
    T *_M_finish;
    T *_M_end_of_storage;
    typedef simple_alloc<T, Alloc> data_allocator;
public:
    typedef T *iterator;
    typedef unsigned int size_type;
    size_type size() const { return _M_finish - _M_start; }
    iterator begin() { return _M_start; }
    iterator end() { return _M_finish; }
    static iterator allocate(size_type n) { return data_allocator::allocate(n); }
    static void deallocate(iterator p, size_type n) { data_allocator::deallocate(p, n); }
    void _M_insert_aux(iterator position, const T& x);
};

template<class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T& x)
{
    if (_M_finish != _M_end_of_storage) {
        construct(_M_finish, *(_M_finish - 1));
        ++_M_finish;
        T x_copy = x;
        copy_backward(position, _M_finish - 2, _M_finish - 1);
        *position = x_copy;
    } else {
        const size_type old_size = size();
        const size_type len = old_size != 0 ? 2 * old_size : 1;
        iterator new_start = allocate(len);
        iterator new_finish = new_start;
        new_finish = uninitialized_copy(_M_start, position, new_start);
        construct(new_finish, x);
        ++new_finish;
        new_finish = uninitialized_copy(position, _M_finish, new_finish);
        destroy(begin(), end());
        deallocate(_M_start, _M_end_of_storage - _M_start);
        _M_start = new_start;
        _M_finish = new_finish;
        _M_end_of_storage = new_start + len;
    }
}

template void vector<light_source *, my_allocator<light_source *> >::_M_insert_aux(light_source **, light_source *const&);
